def find(x, parents):
    if parents[x] != x:
        parents[x] = find(parents[x], parents)
    return parents[x]

def union(x, y, count, parents):
    rootX = find(x, parents)
    rootY = find(y, parents)
    if rootX != rootY:
        if count[rootX] < count[rootY]:
            count[rootX] += count[rootY]
            count[rootY] = rootX
