def get_digits_memoized(f, n):
    # This assumes n is in [0, 1000000]
    if 0 <= n < 10:
        return (n, f[0]*n)
    if n == 10 ** 6:
        return ((math.floor(n // 10), f[1]*math.floor(n // 10)),
                (n % 10, f[1]*(n % 10)))
    ans = frozenset()
