from collections import defaultdict

def bfs(s, t, time):
    level = 0
    visited = set([s])
    prev = defaultdict(lambda: -1)
    queue = [(s, -1)]
    while queue:
        for _ in range(len(queue)):
            u, prev_u = queue.pop(0)
            if u == t:
                return level, prev_u, visited
            for v in adj[u]:
                if level < time or (v not in visited and adj[u][v] < time):
                    visited.add(v)
                    prev[v] = u
                    queue.append((v, u))
        level += 1
    return -1, -1, set()

def dfs(s, t, time, path, visited):
    visited.add(s)
    if s == t:
        return visited
    for v in adj[s]:
        if adj[s][v] > time or v not in visited:
            visited.add(v)
            path.add(v)
            result = dfs(v, t, max(0, adj[s][v] - time), path, visited)
            if result:
                return result
    visited.remove(s)
    return set()

